27	pub struct Aggregation {
28	    pub severities: BTreeMap<PackageId, Severity>,
29	    pub reasons: BTreeMap<PackageId, BumpReason>,
30	    pub named_by: BTreeMap<PackageId, NamedBy>,
31	    /// Changeset files to delete from disk this run (non-pre-mode only: a pre-mode run must never delete a
32	    /// changeset, since it may still be re-applied on the next pre-mode `version` before `pre exit`).
33	    pub consumed: Vec<PathBuf>,
