198	#[allow(clippy::too_many_arguments)]
199	pub fn aggregate<D, I>(
200	    graph: &D,
201	    identity: &IdentityIndex,
202	    config: &ResolvedConfig,
203	    git: &GitAccess<'_>,
204	    tags: &TagIndex,
205	    base_versions: &BTreeMap<PackageId, Version>,
206	    pre: Option<&callisto_model::format::PreState>,
207	    inference: &I,
208	) -> Result<Aggregation, GraphError>
209	where
210	    D: DependencyResolver,
211	    I: SeverityInference,
212	{
213	    let loaded = load_changesets(&config.root, config)?;
214	    let mut agg = Aggregation::default();
215	    // Inference reads `since..HEAD`; in a shallow clone that range is silently shorter than the real one.
216	    if graph.packages().any(|pkg| pkg.release_trigger == ReleaseTrigger::Auto) {
217	        git.require_full_history()?;
218	    }
219	
220	    for pkg in graph.packages() {
221	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
222	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
223	        let last_tag = tags.last_tag(&pkg.id);
224	        let cur_ver = last_tag
225	            .map(|t| t.version.clone())
226	            .or_else(|| base_versions.get(&pkg.id).cloned())
227	            .ok_or_else(|| {
228	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
229	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
230	                    field: "version",
231	                })
232	            })?;
233	
234	        let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
235	        let policy = resolve_package_config(&native_names, config)
236	            .and_then(|pcfg| pcfg.pre_major_inference)
237	            .unwrap_or(PreMajorInferencePolicy::Off);
238	
239	        // release_trigger: Changeset packages take severity from pending changesets only --
240	        // commit inference must not run for them, so neither does resolving its window.
241	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
242	            let since = last_tag
243	                .map(|t| resolve_since(git, tags, t.name.as_str()))
244	                .transpose()?;
245	            let window = crate::infer::InferenceWindowSpec {
246	                pathspecs: &pathspecs,
247	                since,
248	                current_version: &cur_ver,
249	                has_prior_release: last_tag.is_some(),
250	                policy,
251	            };
252	            inference.infer(pkg, git, window)?
253	        } else {
254	            None
255	        };
256	
257	        if let Some(outcome) = inferred
258	            && outcome.severity > cur_sev
259	        {
260	            agg.severities.insert(pkg.id.clone(), outcome.severity);
261	            agg.reasons.insert(
262	                pkg.id.clone(),
263	                BumpReason::Inference {
264	                    commits: outcome.commit_count,
265	                    remapped: outcome.remapped,
266	                },
267	            );
268	            agg.named_by.insert(pkg.id.clone(), NamedBy::Inference);
269	            agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
270	        }
271	    }
272	
273	    // During a pre-release cycle (PreMode::Pre) changesets must NOT be consumed:
274	    // they remain on disk so they can be re-applied when the cycle exits.
275	    let is_pre_mode = pre
276	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
277	        .unwrap_or(false);
278	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
279	    let already_recorded: std::collections::HashSet<&str> = pre
280	        .map(|s| s.changesets.iter().map(String::as_str).collect())
281	        .unwrap_or_default();
282	    let mut recorded_only: std::collections::HashSet<PackageId> = std::collections::HashSet::new();
283	
284	    for cs in loaded {
285	        let is_already_recorded = is_pre_mode && already_recorded.contains(cs.id.as_str());
286	        // Consume a changeset only once an entry resolves; a mixed or fully unresolved one stays on disk and is ignored whole.
287	        let mut has_unresolved = false;
288	        let mut resolved = Vec::new();
289	        for entry in cs.changeset.entries {
290	            let unresolved = match PackageId::parse(&entry.name) {
291	                Err(_) => Some("contains invalid package name"),
292	                Ok(id) => match resolve_target_package(graph.packages(), identity, &id)? {
293	                    Some(target_pkg) => {
294	                        resolved.push((entry, target_pkg));
295	                        continue;
296	                    }
297	                    None => Some("references a package that is not in the workspace:"),
298	                },
299	            };
300	            if let Some(what) = unresolved {
301	                has_unresolved = true;
302	                agg.diagnostics.push(Diagnostic {
303	                    code: callisto_model::DiagnosticCode::UnknownPackage,
304	                    severity: callisto_model::DiagnosticSeverity::Warning,
305	                    message: format!(
306	                        "Changeset `{}` {what} `{}`; none of its entries apply until this entry is fixed or removed",
307	                        cs.path.display(),
308	                        entry.name
309	                    ),
310	                    package: None,
311	                    path: Some(cs.path.clone()),
312	                    governed_by: None,
313	                    escalated_by: None,
314	                });
315	            }
316	        }
317	        if has_unresolved {
318	            continue;
319	        }
320	        let mut matched_any = false;
321	        for (entry, target_pkg) in resolved {
322	            matched_any = true;
323	            let canonical_id = target_pkg.id.clone();
324	            let cur_sev = agg.severities.get(&canonical_id).copied().unwrap_or(Severity::None);
325	            if entry.severity > cur_sev {
326	                agg.severities.insert(canonical_id.clone(), entry.severity);
327	                agg.reasons.insert(
328	                    canonical_id.clone(),
329	                    BumpReason::Changeset {
330	                        changesets: vec![cs.id.clone()],
331	                    },
332	                );
333	                agg.named_by.insert(canonical_id.clone(), NamedBy::Changeset);
334	            }
335	
336	            if entry.severity != Severity::None && is_already_recorded {
337	                recorded_only.insert(canonical_id.clone());
338	            }
339	            if entry.severity != Severity::None && !is_already_recorded {
340	                // In pre-release mode use the pre-cycle entry version as the
341	                // changelog "from" baseline so the log covers the full pre
342	                // range rather than reflecting live (pre-tagged) versions.
343	                let pkg_ver = if is_pre_mode {
344	                    pre.and_then(|s| crate::pre_initial_version(s, &canonical_id))
345	                        .cloned()
346	                        .or_else(|| base_versions.get(&canonical_id).cloned())
347	                        .unwrap_or_else(|| Version::semver(0, 0, 0))
348	                } else {
349	                    tags.last_tag(&canonical_id)
350	                        .map(|t| t.version.clone())
351	                        .or_else(|| base_versions.get(&canonical_id).cloned())
352	                        .unwrap_or_else(|| Version::semver(0, 0, 0))
353	                };
354	                let cl_input = agg
355	                    .changelog_inputs
356	                    .entry(canonical_id.clone())
357	                    .or_insert_with(|| ChangelogInput {
358	                        style: Default::default(),
359	                        package: canonical_id.clone(),
360	                        from: pkg_ver,
361	                        to: None,
362	                        entries: Vec::new(),
363	                    });
364	                cl_input.entries.push(ChangelogEntry {
365	                    severity: entry.severity,
366	                    source: ChangeSource::Changeset {
367	                        filename: cs.id.clone(),
368	                        summary: cs.changeset.summary.clone(),
369	                    },
370	                });
371	            }
372	        }
373	        if matched_any {
374	            if is_pre_mode {
375	                // Records newly-seen ids so a rerun treats them as already-applied and skips the changelog entry.
376	                if !is_already_recorded {
377	                    agg.new_pre_changesets.push(cs.id.clone());
378	                }
379	            } else {
380	                agg.consumed.push(cs.path.clone());
381	            }
382	        }
383	    }
384	
385	    // A package whose only changesets are already recorded in `pre.json` has nothing new to release, so a rerun
386	    // plans no further prerelease for it; recorded changesets still count when a new one names the package.
387	    for id in recorded_only {
388	        if !agg.changelog_inputs.contains_key(&id) && agg.named_by.get(&id) == Some(&NamedBy::Changeset) {
389	            agg.severities.remove(&id);
390	            agg.reasons.remove(&id);
391	            agg.named_by.remove(&id);
392	        }
393	    }
394	
395	    loop {
396	        let mut changed = false;
397	        if union_fixed(&mut agg, &config.groups, base_versions) {
398	            changed = true;
399	        }
400	        if union_linked(&mut agg, &config.groups, base_versions) {
401	            changed = true;
402	        }
403	        if !changed {
404	            break;
405	        }
406	    }
407	
408	    Ok(agg)
409	}
410	
411	pub(crate) fn union_fixed(
412	    agg: &mut Aggregation,
413	    groups: &GroupTable,
414	    base_versions: &BTreeMap<PackageId, Version>,
415	) -> bool {
416	    let mut changed = false;
417	    for g in groups.fixed.values() {
418	        let target = g.max_severity(&agg.severities);
419	        if target == Severity::None {
420	            continue;
421	        }
422	
423	        for m in g.package_members().cloned().collect::<Vec<_>>() {
424	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
425	            if target > cur {
426	                // Skip group members absent from the workspace: inserting one would make `bump_target` fail on a missing base version.
427	                if !base_versions.contains_key(&m) {
428	                    agg.diagnostics.push(Diagnostic {
429	                        code: callisto_model::DiagnosticCode::UnknownPackage,
430	                        severity: callisto_model::DiagnosticSeverity::Warning,
431	                        message: format!(
432	                            "Fixed group `{}` references package `{}` which is not in the \
433	                             workspace; the stale group member is skipped. Remove it from \
434	                             callisto.toml to silence this warning.",
435	                            g.name,
436	                            m.display_name()
437	                        ),
438	                        package: Some(m.clone()),
439	                        path: None,
440	                        governed_by: Some(callisto_model::ConfigKey::FIXED_GROUP),
441	                        escalated_by: None,
442	                    });
443	                    continue;
444	                }
445	                agg.severities.insert(m.clone(), target);
446	                agg.reasons
447	                    .insert(m.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
448	                changed = true;
449	            }
450	        }
451	    }
452	    changed
453	}
454	
455	pub(crate) fn union_linked(
456	    agg: &mut Aggregation,
457	    groups: &GroupTable,
458	    base_versions: &BTreeMap<PackageId, Version>,
459	) -> bool {
460	    let mut changed = false;
461	    for g in groups.linked.values() {
462	        let named_any = g.package_members().any(|id| agg.named_by.contains_key(id));
463	        if !named_any {
464	            continue;
465	        }
466	
467	        // A linked group's target severity comes only from members a changeset or inference named, not stale sibling severities.
468	        let target_sev = g
469	            .package_members()
470	            .filter(|id| agg.named_by.contains_key(*id))
471	            .filter_map(|id| agg.severities.get(id).copied())
472	            .max()
473	            .unwrap_or(Severity::None);
474	
475	        for m in g.package_members().cloned().collect::<Vec<_>>() {
476	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
477	            if target_sev > cur {
478	                // Guard against stale linked-group members, same rationale as
479	                // in `union_fixed`: a removed package must not enter
480	                // `agg.severities`, which would cause `bump_target` to crash.
481	                if !base_versions.contains_key(&m) {
482	                    agg.diagnostics.push(Diagnostic {
483	                        code: callisto_model::DiagnosticCode::UnknownPackage,
484	                        severity: callisto_model::DiagnosticSeverity::Warning,
485	                        message: format!(
486	                            "Linked group `{}` references package `{}` which is not in the \
487	                             workspace; the stale group member is skipped. Remove it from \
488	                             callisto.toml to silence this warning.",
489	                            g.name,
490	                            m.display_name()
491	                        ),
492	                        package: Some(m.clone()),
493	                        path: None,
494	                        governed_by: Some(callisto_model::ConfigKey::LINKED_GROUP),
495	                        escalated_by: None,
496	                    });
497	                    continue;
498	                }
499	                agg.severities.insert(m.clone(), target_sev);
500	                agg.reasons
501	                    .insert(m.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
502	                changed = true;
503	            }
504	        }
505	    }
506	    changed
507	}
