1	use std::collections::BTreeMap;
2	
3	use callisto_model::{
4	    BumpReason, CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, Package, PackageId, Severity,
5	    StatusReport, StrictFlag, PACKAGE_REPORT_SCHEMA_VERSION,
6	};
7	
8	use crate::aggregate::{resolve_target_package, LoadedChangeset};
9	use crate::changed::changed_since_last_tag;
10	use crate::commands::escalate;
11	use crate::commands::version::{plan_version, VersionOptions};
12	use crate::error::GraphError;
13	use crate::identity::IdentityIndex;
14	use crate::infer::SeverityInference;
15	use crate::resolver::DependencyResolver;
16	use crate::Workspace;
17	
18	#[derive(Clone, Debug, Default)]
19	pub struct StatusOptions {
20	    pub strict: bool,
21	}
22	
23	/// Per-package accumulator: pending changeset names and their max severity.
24	type PendingChangesets = BTreeMap<PackageId, (Vec<String>, Option<Severity>)>;
25	
26	/// Resolves each changeset entry to at most one package through the identity index -- the
27	/// resolver `callisto version` uses -- and accumulates the pending changeset names and max
28	/// severity per package.
29	///
30	/// An unknown or ambiguous entry is skipped here rather than hard-erroring:
31	/// `changeset_wellformedness_diagnostics` reports both cases as an Error-severity diagnostic.
32	fn resolve_pending_changesets<'a>(
33	    packages: impl Iterator<Item = &'a Package> + Clone,
34	    identity: &IdentityIndex,
35	    loaded_changesets: &[LoadedChangeset],
36	) -> Result<PendingChangesets, GraphError> {
37	    let mut pending: PendingChangesets = BTreeMap::new();
38	    for lc in loaded_changesets {
39	        for entry in &lc.changeset.entries {
40	            let Ok(entry_id) = PackageId::parse(&entry.name) else {
41	                continue;
42	            };
43	            let resolved = match resolve_target_package(packages.clone(), identity, &entry_id) {
44	                Ok(Some(resolved)) => resolved,
45	                Ok(None) | Err(GraphError::AmbiguousName { .. }) => continue,
46	                Err(e) => return Err(e),
47	            };
48	            let name = lc
49	                .path
50	                .file_stem()
51	                .and_then(|s| s.to_str())
52	                .unwrap_or("unknown")
53	                .to_string();
54	            let state = pending.entry(resolved.id.clone()).or_default();
55	            if state.0.last() != Some(&name) {
56	                state.0.push(name);
57	            }
58	            state.1 = match (state.1, entry.severity) {
59	                (None, s) => Some(s),
60	                (Some(cur), s) => Some(cur.max(s)),
61	            };
62	        }
63	    }
64	    Ok(pending)
65	}
66	
67	pub fn status<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
68	    ws: &Workspace<'_, R, D>,
69	    inference: &I,
70	    opts: &StatusOptions,
71	) -> Result<StatusReport, GraphError> {
72	    let mut packages = Vec::new();
73	    let ids = ws.report_ids();
74	    let base_versions = ws.base_versions()?;
75	    let (loaded_changesets, changeset_load_failures) = crate::load_changesets_permissive(&ws.root, &ws.config)?;
76	    let tags = ws.tags()?;
77	
78	    let all_packages: Vec<&Package> = ws.graph.packages().collect();
79	    let pending = resolve_pending_changesets(all_packages.iter().copied(), &ws.identity, &loaded_changesets)?;
80	
81	    // Pending severity is `plan_version`'s `PlannedBump.severity`; status computes no cascade of its own.
82	    let version_opts = VersionOptions {
83	        strict: opts.strict,
84	        allow_empty_changesets: true,
85	    };
86	    // `plan_version` hard-errors on an ambiguous entry or unparseable changeset; status reports the diagnostic and skips severity planning.
87	    let plan = match plan_version(ws, inference, &version_opts) {
88	        Ok(plan) => Some(plan),
89	        Err(GraphError::AmbiguousName { .. } | GraphError::ParseChangeset { .. }) => None,
90	        Err(e) => return Err(e),
91	    };
92	    let planned_severity: BTreeMap<PackageId, Severity> = plan
93	        .iter()
94	        .flat_map(|plan| &plan.bumps)
95	        .map(|b| (b.package.clone(), b.severity))
96	        .collect();
97	
98	    let changed = changed_since_last_tag(&all_packages, tags, ws.git_access())?;
99	
100	    for pkg in all_packages.iter().copied() {
101	        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
102	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
103	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
104	                field: "version",
105	            })
106	        })?;
107	        let last = tags.last_tag(&pkg.id);
108	        let last_tag = last.map(|t| t.name.clone());
109	        let last_released_version = last.map(|t| t.version.clone());
110	
111	        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
112	        let pending_severity = planned_severity.get(&pkg.id).copied();
113	
114	        packages.push(callisto_model::StatusPackageRecord {
115	            package: ids.of(&pkg.id),
116	            current_version,
117	            last_tag,
118	            last_released_version,
119	            pending_severity,
120	            changed_since_last_tag: changed[&pkg.id],
121	            release_trigger: pkg.release_trigger,
122	            pending_changesets: pkg_changesets,
123	        });
124	    }
125	
126	    let mut diagnostics = ws.graph.diagnostics().to_vec();
127	    diagnostics.extend(tags.diagnostics.iter().cloned());
128	    // Fold in every changeset well-formedness diagnostic (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
129	    // InvalidPackageName).
130	    diagnostics.extend(changeset_wellformedness_diagnostics(
131	        all_packages.iter().copied(),
132	        &ws.identity,
133	        &loaded_changesets,
134	    )?);
135	    for failure in &changeset_load_failures {
136	        diagnostics.push(Diagnostic {
137	            code: DiagnosticCode::ChangesetParseFailed,
138	            severity: DiagnosticSeverity::Error,
139	            message: format!("{}: {}", failure.path.display(), failure.source),
140	            package: None,
141	            path: Some(failure.path.clone()),
142	            governed_by: None,
143	            escalated_by: None,
144	        });
145	    }
146	    for bump in plan.iter().flat_map(|plan| &plan.bumps) {
147	        let Some(BumpReason::Inference { commits, .. }) = &bump.reason else {
148	            continue;
149	        };
150	        let has_changeset = packages
151	            .iter()
152	            .any(|record| record.package == ids.of(&bump.package) && !record.pending_changesets.is_empty());
153	        if has_changeset {
154	            continue;
155	        }
156	        diagnostics.push(Diagnostic {
157	            code: DiagnosticCode::InferredReleaseWithoutChangeset,
158	            severity: DiagnosticSeverity::Warning,
159	            message: format!(
160	                "`{}` has a pending release inferred from {commits} commit(s) and no changeset; the release pull request reads changesets only, so add one to release it",
161	                bump.package.display_name()
162	            ),
163	            package: Some(bump.package.clone()),
164	            path: None,
165	            governed_by: None,
166	            escalated_by: None,
167	        });
168	    }
169	    // The plan's strict-escalatable warnings, so `status --strict` fails where `version --strict` does.
170	    for d in plan.iter().flat_map(|plan| &plan.diagnostics) {
171	        let reported = diagnostics
172	            .iter()
173	            .any(|seen| seen.code == d.code && seen.message == d.message);
174	        if d.escalated_by == Some(StrictFlag::Strict) && !reported {
175	            diagnostics.push(d.clone());
176	        }
177	    }
178	    escalate(&mut diagnostics, opts.strict);
179	    ids.diagnostics(&mut diagnostics);
180	
181	    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
182	    // Packages with a planned bump, after cascade and groups. A script reads this to detect pending changesets,
183	    // because `--check` gates on errors only.
184	    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;
185	
186	    Ok(StatusReport {
187	        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
188	        has_changesets,
189	        pending,
190	        packages,
191	        diagnostics,
192	    })
193	}
194	
195	/// The per-changeset well-formedness diagnostics: entries shape and package-name resolution. Resolves through the same identity index
196	/// `resolve_pending_changesets` does, but this scan must never abort early,
197	/// so an unknown or ambiguous entry becomes a diagnostic instead of an
198	/// early return.
199	///
200	/// An entries-empty changeset is advisory only (`Info`): `@changesets/cli add --empty`
201	/// produces one deliberately, so it is not a well-formedness problem. A changeset with
202	/// entries but an empty summary never reaches this scan at all -- `load_changesets_permissive`
203	/// already rejects that shape at parse time, surfacing it as a `ChangesetParseFailed`
204	/// diagnostic instead.
205	fn changeset_wellformedness_diagnostics<'a>(
206	    packages: impl Iterator<Item = &'a Package> + Clone,
207	    identity: &IdentityIndex,
208	    loaded: &[LoadedChangeset],
209	) -> Result<Vec<Diagnostic>, GraphError> {
210	    let mut diagnostics = Vec::new();
211	    for cs in loaded {
212	        if cs.changeset.entries.is_empty() {
213	            diagnostics.push(Diagnostic {
214	                code: DiagnosticCode::EmptyChangeset,
215	                severity: DiagnosticSeverity::Info,
216	                message: format!("Changeset `{}` is empty", cs.path.display()),
217	                package: None,
218	                path: Some(cs.path.clone()),
219	                governed_by: None,
220	                escalated_by: None,
221	            });
222	        }
223	
224	        for entry in &cs.changeset.entries {
225	            match PackageId::parse(&entry.name) {
226	                Ok(id) => match resolve_target_package(packages.clone(), identity, &id) {
227	                    Ok(None) => {
228	                        diagnostics.push(Diagnostic {
229	                            code: DiagnosticCode::UnknownPackage,
230	                            severity: DiagnosticSeverity::Error,
